#include <stdio.h>
#include <string.h>

/**
Write "Congratulations, <username>!" to a buffer. The buffer will be printed by the caller.

@param buffer: the buffer to write to
@param buffer_size: the size of the buffer
@param userName: the username to congratulate
@param userName_size: the size of the username
*/
void congratulate_user(char* buffer, int buffer_size, const char *userName, int userName_size)
{
    const char* prefix = "Congratulations, ";
    int prefix_len = strlen(prefix);

    // Calculate the maximum possible length of the final string.
    // This includes the prefix, the username, and the null terminator.
    int max_len = prefix_len + userName_size + 1;

    // If the buffer is not large enough to hold the entire string,
    // we need to truncate.
    if (buffer_size < max_len) {
        // Copy as much of the prefix as possible, ensuring null termination.
        strncpy(buffer, prefix, buffer_size - 1);
        buffer[buffer_size - 1] = '\0'; // Ensure null termination

        // Calculate remaining space for the username.
        int current_len = strlen(buffer);
        int remaining_space = buffer_size - current_len - 1;

        // Append as much of the username as possible, if there's space.
        if (remaining_space > 0) {
            strncat(buffer, userName, remaining_space);
        }
    } else {
        // If the buffer is large enough, construct the full string.
        // Copy the prefix.
        strcpy(buffer, prefix);
        // Append the username.
        strcat(buffer, userName);
        // The null terminator is automatically handled by strcat if there's space.
        // However, to be absolutely safe, we can ensure it if buffer_size is exactly max_len.
        if (buffer_size == max_len) {
            buffer[buffer_size - 1] = '\0';
        }
    }
}
